query:
SELECT 
  (SELECT COUNT(*) FROM raw_materials) as total_raw_materials,
  (SELECT COUNT(*) FROM raw_materials WHERE type = 'huile_essentielle') as huiles_essentielles,
  (SELECT COUNT(*) FROM raw_materials WHERE type = 'absolue') as absolues,
  (SELECT COUNT(*) FROM raw_materials WHERE type = 'extrait_co2') as extraits_co2,
  (SELECT COUNT(*) FROM raw_materials WHERE type = 'concrete') as concretes,
  (SELECT COUNT(*) FROM raw_materials WHERE type = 'resinoid') as resinoids;

SELECT DISTINCT type FROM raw_materials;

SELECT name, type, plant_id FROM raw_materials WHERE type IN ('huile_essentielle', 'absolue', 'extrait_co2') LIMIT 30;

